import axios from "axios";
import { useState, useEffect } from "react";
import { useParams } from "react-router-dom";


export const useProductView = () => {
  const {  documentId } = useParams();
  const [product, setProduct] = useState(null);
  const [selectedColor, setSelectedColor] = useState("");
  const [selectedSize, setSelectedSize] = useState("");
  const [selectedQuantity, setSelectedQuantity] = useState(1);

  const handleQuantityChange = ({ target: { value } }) => {
    setSelectedQuantity(value);
  };

  const getImage = (colour) => {
    if (!product || !product.image) return "";
    const image = product.image.find((img) => img.name.includes(colour));
    return image ? image.url : "";
  };

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await axios.get(
          `http://localhost:1337/api/products/${documentId}?populate=*`
        );
        const productData = response.data.data;
        setProduct(productData);

        // Set default values for color and size
        if (productData?.colors?.length) {
          setSelectedColor(productData.colors[0].name);
        }
        if (productData?.sizes?.length) {
          setSelectedSize(productData.sizes[0].name);
        }
      } catch (error) {
        console.error("Error fetching product:", error);
      }
    };

    if (documentId) fetchProduct();
  }, [documentId]);

  return {
    product,
    getImage,
    selectedSize,
    selectedColor,
    selectedQuantity,
    setSelectedColor,
    setSelectedSize,
    handleQuantityChange,
  };
};
